# Let me think about this from a different angle
# What if the algorithm is: fill with decreasing values starting from boundary?

from collections import deque

def analyze_fill_pattern(grid):
    h, w = len(grid), len(grid[0])

    # First, mark everything that's "inside" the shape
    # Start from all edge zeros and flood fill
    outside = set()
    queue = deque()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == 0 and (r == 0 or r == h-1 or c == 0 or c == w-1):
                outside.add((r, c))
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in outside and grid[nr][nc] == 0:
                outside.add((nr, nc))
                queue.append((nr, nc))

    # Now for each enclosed zero, compute "depth" = max steps to reach outside via a path that doesn't cross input 1s
    # Actually simpler: BFS from each enclosed zero until hitting any cell that was reachable from outside

    enclosed = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 0 and (r,c) not in outside]

    print(f"Enclosed cells: {enclosed}")

    # Compute for each enclosed cell: how many steps to hit "original 1-bounds"?
    def manhattan_from_center(r, c):
        # Center appears to be (3,3)
        cr, cc = 3, 3
        return abs(r - cr) + abs(c - cc)

    def chebyshev_from_center(r, c):
        cr, cc = 3, 3
        return max(abs(r - cr), abs(c - cc))

    print("\nDistance from (3,3) [value 0 cell]:")
    for r, c in sorted(enclosed, key=lambda x: chebyshev_from_center(x[0], x[1])):
        m = manhattan_from_center(r, c)
        ch = chebyshev_from_center(r, c)
        out_val = 0
        for ro in range(h):
            for co in range(w):
                if ro == r and co == c:
                    out_val = output_grid[ro][co]
                    break
            if out_val != 0:
                break
        print(f"({r},{c}): Manhattan={m}, Chebyshev={ch}, Output={out_val}")

