    queue = deque()

    for r in range(h):
        for c in range(w):
            if labeled_array[r][c] != comp_label:
                if r == 0 or r == h-1 or c == 0 or c == w-1:
                    outside.add((r, c))
                    queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in outside and labeled_array[nr][nc] != comp_label:
