from collections import deque

def transform_grid(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    ones_set = set((r,c) for r in range(h) for c in range(w) if input_grid[r][c] == 1)

    # Initialize output with same size
    output = [[0]*w for _ in range(h)]

    # Copy original 1s
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == 1:
                output[r][c] = 1

    # Step 1: Find enclosed zeros using flood fill from outside
    outside = set()
    queue = deque()
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == 0 and (r == 0 or r == h-1 or c == 0 or c == w-1):
                outside.add((r, c))
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in outside and input_grid[nr][nc] == 0:
                outside.add((nr, nc))
                queue.append((nr, nc))

    enclosed_zeros = set((r,c) for r in range(h) for c in range(w) 
                         if input_grid[r][c] == 0 and (r,c) not in outside)

    # Step 2: Find non-enclosed zeros adjacent to 1s → these become 2
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == 0 and (r,c) not in outside:
                if not is_adjacent_to_1(r, c, h, w, ones_set):
                    continue  # This is an enclosed zero
                # It's a non-enclosed zero adjacent to 1 → becomes 2
                output[r][c] = 2

    # Step 3: Among enclosed zeros:
    # - Those not adjacent to ANY 1 → become 0 (center point(s))
    # - Those adjacent to at least one 1 → become 3
    non_adj_1_enclosed = []
    adj_1_enclosed = []
    for pos in enclosed_zeros:
        if is_adjacent_to_1(*pos, h, w, ones_set):
            adj_1_enclosed.append(pos)
        else:
            non_adj_1_enclosed.append(pos)

    print(f"Non-adjacent-to-1 enclosed (potential centers): {non_adj_1_enclosed}")
    print(f"Adjacent-to-1 enclosed (become 3): {len(adj_1_enclosed)}")

    # Mark as 3 first
    for pos in adj_1_enclosed:
        r, c = pos
        output[r][c] = 3

    # For non-adjacent, mark as 0
    for pos in non_adj_1_enclosed:
        r, c = pos
        output[r][c] = 0

    return output

