from collections import deque

def analyze_distance_based(input_grid):
    h, w = len(input_grid), len(input_grid[0])
    ones_positions = set((r,c) for r in range(h) for c in range(w) 
                         if input_grid[r][c] == 1)

    # Compute BFS distances (Chebyshev - use max instead of sum)
    dist_map = np.full((h,w), float('inf'))
    bfs_q = deque()
    for r,c in ones_positions:
        dist_map[r,c] = 0
        bfs_q.append((r,c))

    while bfs_q:
        r, c = bfs_q.popleft()
        d = int(dist_map[r,c])
        for dr,dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r+dr, c+dc
            if 0<=nr<h and 0<=nc<w and dist_map[nr,nc]==float('inf'):
                dist_map[nr,nc] = d + 1  # Chebyshev distance
                bfs_q.append((nr,nc))

    # Get all inside zeros
    outside = set()
    queue = deque()
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == 0 and (r == 0 or r == h-1 or c == 0 or c == w-1):
                outside.add((r, c))
                queue.append((r, c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and (nr,nc) not in outside and input_grid[nr][nc] == 0:
                outside.add((nr, nc))
                queue.append((nr, nc))

    inside_zeros = set((r,c) for r in range(h) for c in range(w) 
                       if input_grid[r][c] == 0 and (r,c) not in outside)

    # Find max distance among inside zeros
    depths = {pos: int(dist_map[r,c]) for r,c in inside_zeros}
    max_d = max(depths.values()) if depths else 0
    deepest_points = [pos for pos, d in depths.items() if d == max_d]

    print(f"Max depth among inside zeros: {max_d}")
    print(f"Deepest points: {sorted(deepest_points)}")

    # For each unique depth value, count how many inside zeros have it
    print("\nDepth distribution:")
    for d in sorted(set(depths.values())):
        count = sum(1 for p, dp in depths.items() if dp == d)
        print(f"  Depth {d}: {count} cells")

    return deepest_points, depths

