    # Find all outside-reachable zeros (can reach from image boundary without crossing 1s)
    outside = set()
    queue = deque()
    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == 0 and (r==0 or r==h-1 or c==0 or c==w-1):
                outside.add((r,c))
                queue.append((r,c))

    while queue:
        r, c = queue.popleft()
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w:
                if (nr, nc) not in outside and input_grid[nr][nc] == 0:
                    outside.add((nr, nc))
                    queue.append((nr, nc))

    # Interior zeros = all zeros NOT reachable from outside
    all_zeros = set((r,c) for r in range(h) for c in range(w) if input_grid[r][c] == 0)
    interior_zeros = all_zeros - outside

    print(f"Total interior zeros: {len(interior_zeros)}")

    # For each interior zero, compute min Chebyshev distance to nearest 1
    def chebyshev_dist_to_ones(r, c):
        min_d = float('inf')
        for r1, c1 in ones_positions:
            d = max(abs(r-r1), abs(c-c1))
            min_d = min(min_d, d)
        return min_d

    # Classify by distance threshold
    dists = [(pos, chebyshev_dist_to_ones(*pos)) for pos in interior_zeros]
    dists.sort(key=lambda x: x[1])

    print("\nInterior zero distances:")
    for pos, d in dists[:15]:
        print(f"  {pos}: distance={d}")

    # Determine the threshold
    # The farthest point(s) should be 0 (center), others become 3
