    center_candidates = [pos for pos, d in dists if d == max_dist]
    print(f"\nMax distance: {max_dist}, Center candidates: {center_candidates}")

    # Apply transformation
    # Inside shape: if adjacent to 1 → 3, else if max dist → 0
    # Outside: if adjacent to 1 → 2
    for r, c in interior_zeros:
        # Check if adjacent to any 1
        adj = False
        for dr, dc in [(0,1),(0,-1),(1,0),(-1,0)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < h and 0 <= nc < w and input_grid[nr][nc] == 1:
