def solve_distance_layers(input_grid):
    """Fill based on distance from 1s boundary"""

    h, w = len(input_grid), len(input_grid[0])
    output = [[0]*w for _ in range(h)]

    ones_positions = set((r,c) for r in range(h) for c in range(w) if input_grid[r][c] == 1)

