    for r in range(h):
        for c in range(w):
            if input_grid[r][c] == 1:
                output[r][c] = 1

    # Distance transform from all 1s (using 4-connectivity for BFS)
    dist_map = np.full((h, w), float('inf'))
    queue = deque()

